using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpStdioServer.Tools;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool("fetch_post"), Description("Fetches a post by ID from an external API.")]
    public static async Task<string> FetchPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric post ID to retrieve.")] int id)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync($"/posts/{id}");
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync();
    }
}

using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpStdioServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a prompt that asks an LLM to summarize the given text.")]
    public static GetPromptResult Summarize(
        [Description("The text to summarize.")] string text)
    {
        return new GetPromptResult
        {
            Description = "Summarize the provided text",
            Messages =
            [
                new PromptMessage
                {
                    Role = Role.User,
                    Content = new Content
                    {
                        Type = "text",
                        Text = $"Please provide a concise summary of the following text:\n\n{text}"
                    }
                }
            ]
        };
    }
}

